 | sed -e '/^\/\/\/ Tokenizes one log line/,/^}/d' > $H/src/oracle.rs
cat > $H/src/main.rs <<'EOF'
mod oracle;
use std::time::Instant;
use logscan::{tokenize, Token, LexError};

fn all(mut it: impl Iterator<Item = Result<Token<'static>, LexError>>) -> Vec<Option<Result<Token<'static>, LexError>>> {
    let mut v = Vec::new();
    loop { let t = it.next(); let end = t.is_none(); v.push(t); if end { v.push(it.next()); v.push(it.next()); return v; } }
}
fn check(s: &str) {
    let s: &'static str = Box::leak(s.to_owned().into_boxed_str());
    let (a, b) = (all(oracle::Tokens::new(s)), all(tokenize(s)));
    assert_eq!(a, b, "mismatch on {s:?}");
}
fn exhaustive() {
    let alpha = [" ", "\t", "[", "]", "\"", "\\", "=", "a", "n", "é"];
    let mut count = 0u64;
    let mut idx: Vec<usize> = Vec::new();
    for len in 0..=7 {
        idx.clear(); idx.resize(len, 0);
        loop {
            let s: String = idx.iter().map(|&i| alpha[i]).collect();
            check(&s); count += 1;
            let mut k = 0;
            while k < len { idx[k] += 1; if idx[k] < alpha.len() { break; } idx[k] = 0; k += 1; }
            if k == len { break; }
        }
    }
    println!("exhaustive: {count} lines identical");
}
struct Lcg(u64);
impl Lcg { fn next(&mut self) -> u64 { self.0 = self.0.wrapping_mul(6364136223846793005).wrapping_add(1442695040888963407); self.0 >> 33 } }
fn corpus(bytes: usize, bad_every: u64) -> Vec<String> {
    let mut r = Lcg(42); let mut out = Vec::new(); let mut total = 0;
    let frags = ["level=info", "level=warn", "msg=\"disk 91% full\"", "msg=\"say \\\"hi\\\"\\n\"", "user=ann", "retries=", "done",
                 "latency_ms=1234", "path=/var/log/app.log", "worker-3", "trace=\"a\\tb\"", "id=7f3a9c"];
    let bads = ["x=\"open", "[nested[", "a\"b", "=v", "q=\"\\x\""];
    while total < bytes {
        let mut l = format!("[2024-05-01T12:{:02}:{:02}Z]", r.next() % 60, r.next() % 60);
        for _ in 0..(3 + r.next() % 8) { l.push(' '); l.push_str(frags[(r.next() % frags.len() as u64) as usize]); }
        if bad_every > 0 && r.next() % bad_every == 0 { l.push(' '); l.push_str(bads[(r.next() % bads.len() as u64) as usize]); }
        total += l.len(); out.push(l);
    }
    out
}
fn count<'a, I: Iterator<Item = Result<Token<'a>, LexError>>>(lines: &'a [String], f: impl Fn(&'a str) -> I) -> u64 {
    let mut n = 0u64;
    for l in lines { for t in f(l) { match t { Ok(Token::Key(k)) => n += k.len() as u64, Ok(_) => n += 1, Err(_) => { n += 1000; break; } } } }
    n
}
fn bench() {
    let lines = corpus(400 << 20, 50);
    let mb = lines.iter().map(|l| l.len()).sum::<usize>() as f64 / 1048576.0;
    for l in lines.iter().take(200_000) { check(l); }
    println!("corpus: {} lines, {mb:.0} MiB, first 200k identical", lines.len());
    let (mut best_old, mut best_new) = (f64::MAX, f64::MAX);
    for _ in 0..7 {
        let t = Instant::now(); let a = count(&lines, |l| oracle::Tokens::new(l)); let o = t.elapsed().as_secs_f64();
        let t = Instant::now(); let b = count(&lines, |l| tokenize(l)); let n = t.elapsed().as_secs_f64();
        assert_eq!(a, b);
        best_old = best_old.min(o); best_new = best_new.min(n);
    }
    println!("old: {:.0} MiB/s   new: {:.0} MiB/s   new/old time: {:.3}", mb / best_old, mb / best_new, best_new / best_old);
}
fn main() {
    match std::env::args().nth(1).as_deref() { Some("bench") => bench(), Some("exh") => exhaustive(), _ => { exhaustive(); bench(); } }
}
EOF
